def rej(field, code, ru, en):
    return {"field": field, "code": code, "ru": ru, "en": en}


def fnv(s):
    h = 2166136261
    for ch in s.encode("utf-8"):
        h ^= ch
        h = (h * 16777619) & 0xFFFFFFFF
    return h


class Rng:  # mulberry32, как у кофейни и машиниста
    def __init__(self, seed):
        self.a = seed & 0xFFFFFFFF

    def u(self):
        self.a = (self.a + 0x6D2B79F5) & 0xFFFFFFFF
        t = self.a
        t = ((t ^ (t >> 15)) * (t | 1)) & 0xFFFFFFFF
        t ^= (t + (((t ^ (t >> 7)) * (t | 61)) & 0xFFFFFFFF)) & 0xFFFFFFFF
        return ((t ^ (t >> 14)) & 0xFFFFFFFF) / 4294967296.0


def clock(t):
    t = int(t + 0.5)
    return "%02d:%02d:%02d" % (13 + t // 3600, (t // 60) % 60, t % 60)


def load(city):
    w, m = DATA[city]
    return json.loads(json.dumps(w)), json.loads(json.dumps(m))


# ---------- мир по зерну: всё с тригонометрией и степенями здесь ----------
def make_world(seed, city):
    W, M = load(city)
    day = W["days"][(seed - 1) % len(W["days"])]
    R = lambda label: Rng(fnv(str(seed) + ":" + city + ":" + label))
    zc = M["depot"]["z"]
    hours = []      # часы 12..16, смена с 13:00 (индекс 1)
    re = R("forecast")
    for k in range(len(day["hours"])):
        w10, w100 = day["wind_speed_10m"][k], day["wind_speed_100m"][k]
        d10, d100 = day["wind_direction_10m"][k], day["wind_direction_100m"][k]
        t2 = day["temperature_2m"][k]
        truth, fc = {}, {}
        es, ed = 1.0 + 0.36 * (re.u() - 0.5), 36.0 * (re.u() - 0.5)  # О: ошибка прогноза ±18 % по силе, ±18° по направлению
        for a in ALTS:
            s = w10 + (w100 - w10) * math.log(a / 10.0) / math.log(10.0)  # логарифмический профиль между 10 и 100 м
            s = max(0.0, s)
            dr = d10 if a < 60 else d100
            # направление «откуда дует» → вектор «куда»: x на восток, y на север
            truth[a] = [-s * math.sin(math.radians(dr)), -s * math.cos(math.radians(dr))]
            sf, df = s * es, dr + ed
            fc[a] = [-sf * math.sin(math.radians(df)), -sf * math.cos(math.radians(df))]
        # плотность по высоте над уровнем моря: множитель мощности sqrt(ρ0/ρ) через каждые 100 м от 0 до 3 000 м
        dens = []
        for z in range(0, 3100, 100):
            T = t2 + 273.15 - 0.0065 * (z - zc)
            p = 101325.0 * (1 - 2.25577e-5 * z) ** 5.25588
            rho = p / (287.05 * T)
            dens.append(math.sqrt(1.225 / rho))
        cap = 1.0 if t2 >= 15 else (0.85 + 0.15 * t2 / 15.0 if t2 >= 0 else (0.85 + 0.015 * t2 if t2 >= -20 else 0.55))  # О: −15 % при 0 °C, −30 % при −10 °C
        pmax = D["pmax_w"] if t2 <= D["pmax_hot_c"] else max(D["pmax_46_w"], D["pmax_w"] - (t2 - D["pmax_hot_c"]) * (D["pmax_w"] - D["pmax_46_w"]) / 6.0)
        gust_k = max(0.0, day["wind_gusts_10m"][k] / max(0.5, w10) - 1.0)
        hours.append({"truth": truth, "fc": fc, "t": t2, "t_fc": round(t2 + 2.0 * (re.u() - 0.5), 1), "dens": dens, "cap": cap, "pmax": pmax, "gust_k": gust_k})
    # порывы: на каждые 10 с множитель силы ветра 1 + k·r², r случайно (скрыто)
    rg = R("gust"); gust = []
    for i in range(END_S // 10 + 1):
        hk = hours[min(len(hours) - 1, 1 + i * 10 // 3600)]["gust_k"]
        r = rg.u(); gust.append(1.0 + 0.6 * hk * r * r)
    # заказы
    ro = R("orders"); pts = M["points"]; orders = []
    n = 12 + int(ro.u() * 5)
    for i in range(n):
        t = int(ro.u() * 5400)
        p = pts[int(ro.u() * len(pts))]
        kg = round(2 + 28 * ro.u() * ro.u(), 1)
        orders.append({"t": t, "point": p["id"], "kg": kg, "due": t + 1500 + int(ro.u() * 1500)})
    orders.sort(key=lambda o: (o["t"], o["point"]))
    for i, o in enumerate(orders):
        o["id"] = i
    return {"seed": seed, "city": city, "day": day["day"], "hours": hours, "gust": gust, "orders": orders,
            "map": {"depot": M["depot"], "points": pts, "nofly": M["nofly"], "terrain": M["terrain"]}}


def seg_circle(ax, ay, bx, by, cx, cy, r):
    """Проходит ли отрезок AB через круг (центр C, радиус r)."""
    dx, dy = bx - ax, by - ay; L2 = dx * dx + dy * dy
    t = 0.0 if L2 == 0 else ((cx - ax) * dx + (cy - ay) * dy) / L2
    t = 0.0 if t < 0 else (1.0 if t > 1 else t)
    px, py = ax + t * dx - cx, ay + t * dy - cy
    return px * px + py * py < r * r


class Game:
    def __init__(self, seed, city, world=None):
        self.city = city
        self.W = world if world is not None else make_world(seed, city)
        self.M = self.W["map"]; self.pts = {p["id"]: p for p in self.M["points"]}
        self.t = 0.0
        self.drones = [{"id": i, "mode": "dock", "x": 0.0, "y": 0.0, "agl": 0.0, "soc": 1.0, "load": [], "route": [], "wp": 0,
                        "phase": "", "alt": 60, "va": 12.0, "busy": 0.0, "gs": 0.0, "wh": 0.0, "pads": 0} for i in range(3)]
        self.orders = [dict(o, status="wait", drone=None, at=None) for o in self.W["orders"]]
        self.counts = {"delivered": 0, "late_s": 0.0, "forced": 0, "lost": 0, "pads": 0, "wh": 0.0, "ref_wh": 0.0}
        self.journal = []; self.events = []

    # ---------- окружение ----------
    def hour(self):
        return self.W["hours"][min(len(self.W["hours"]) - 1, 1 + int(self.t) // 3600)]

    def ground(self, x, y):
        T = self.M["terrain"]; fx = (x - T["x0"]) / T["step"]; fy = (y - T["y0"]) / T["step"]
        i = int(fx); j = int(fy)
        i = 0 if i < 0 else (T["nx"] - 2 if i > T["nx"] - 2 else i); j = 0 if j < 0 else (T["ny"] - 2 if j > T["ny"] - 2 else j)
        ax, ay = fx - i, fy - j; ax = 0.0 if ax < 0 else (1.0 if ax > 1 else ax); ay = 0.0 if ay < 0 else (1.0 if ay > 1 else ay)
        z = T["z"]; n = T["nx"]
        return (z[j * n + i] * (1 - ax) * (1 - ay) + z[j * n + i + 1] * ax * (1 - ay) + z[(j + 1) * n + i] * (1 - ax) * ay + z[(j + 1) * n + i + 1] * ax * ay)

    def wind(self, alt, truth=True):
        """Ветер на высоте полёта сейчас: линейно между часами, с порывом (скрыто). Вектор «куда», м/с."""
        hs = self.W["hours"]; f = self.t / 3600.0 + 1.0; i = int(f); i = len(hs) - 2 if i > len(hs) - 2 else i; a = f - i
        key = "truth" if truth else "fc"
        u = hs[i][key][alt][0] * (1 - a) + hs[i + 1][key][alt][0] * a; v = hs[i][key][alt][1] * (1 - a) + hs[i + 1][key][alt][1] * a
        if truth:
            g = self.W["gust"][int(self.t) // 10]; u *= g; v *= g
        return u, v

    def dens(self, z):
        d = self.hour()["dens"]; f = z / 100.0; i = int(f); i = 0 if i < 0 else (len(d) - 2 if i > len(d) - 2 else i); a = f - i
        a = 0.0 if a < 0 else (1.0 if a > 1 else a)
        return d[i] * (1 - a) + d[i + 1] * a

    def mass(self, dr):
        return D["empty_kg"] + sum(self.orders[o]["kg"] for o in dr["load"])

    def p_hover(self, m, z):
        return D["hover_c"] * m * math.sqrt(math.sqrt(m)) * self.dens(z)

    def target(self, tok):
        if tok == "depot":
            return self.M["depot"]
        if tok[0] == "o":
            return self.pts[self.orders[int(tok[1:])]["point"]]
        return self.pts[int(tok[1:])]

    # ---------- Проверка игры ----------
    def check(self, dec):
        out = []
        i = dec.get("drone")
        if not isinstance(i, int) or i < 0 or i > 2:
            return [rej("drone", "unknown", "Дронов три: 0, 1 и 2.", "There are three drones: 0, 1 and 2.")]
        dr = self.drones[i]
        if dec.get("recall"):
            if dr["mode"] != "air":
                out.append(rej("recall", "not_air", "Дрон %d не в воздухе." % i, "Drone %d is not in the air." % i))
            return out
        route = dec.get("route")
        if dr["mode"] != "dock":
            return [rej("drone", "busy", "Дрон %d сейчас не на складе." % i, "Drone %d is not at the depot." % i)]
        if dr["busy"] > 0:
            return [rej("drone", "swap", "Дрон %d меняет батарею, ещё %d с." % (i, int(dr["busy"] + 0.999)), "Drone %d is swapping its battery, %d s more." % (i, int(dr["busy"] + 0.999)))]
        if not isinstance(route, list) or not route or len(route) > 5:
            return [rej("route", "len", "Маршрут: от 1 до 5 остановок.", "A route has 1 to 5 stops.")]
        if dec.get("alt", 60) not in ALTS:
            out.append(rej("alt", "alt", "Высота полёта: 30, 60, 100 или 120 м.", "Altitude: 30, 60, 100 or 120 m."))
        if dec.get("speed", "eco") not in SPEEDS:
            out.append(rej("speed", "speed", "Скорость: эконом или быстро.", "Speed: eco or fast."))
        kg = 0.0; seen = set(); pts = [self.M["depot"]]
        for tok in route:
            if not isinstance(tok, str) or len(tok) < 2 or tok[0] not in "op" or not tok[1:].isdigit():
                out.append(rej("route", "token", "Остановка «%s» не заказ (o…) и не площадка (p…)." % tok, "Stop '%s' is neither an order (o…) nor a pad (p…)." % tok)); continue
            n = int(tok[1:])
            if tok[0] == "o":
                if n >= len(self.orders) or self.orders[n]["t"] > self.t:
                    out.append(rej("route", "no_order", "Заказа %d ещё нет." % n, "Order %d does not exist yet." % n)); continue
                o = self.orders[n]
                if o["status"] != "wait" or n in seen:
                    out.append(rej("route", "taken", "Заказ %d уже доставлен или в пути." % n, "Order %d is already delivered or on its way." % n)); continue
                seen.add(n); kg += o["kg"]
            else:
                if n not in self.pts or not self.pts[n]["pad"]:
                    out.append(rej("route", "no_pad", "Точка %d не площадка зарядки." % n, "Point %d is not a charging pad." % n)); continue
            pts.append(self.target(tok))
        if out:
            return out
        if kg > D["payload_max"] or D["empty_kg"] + kg > D["mtow_kg"]:
            out.append(rej("route", "mass", "Груз %.1f кг: дрон берёт не больше 40 кг, взлётная масса до 95 кг." % kg, "Load %.1f kg: the drone takes at most 40 kg, take-off mass up to 95 kg." % kg))
        pts.append(self.M["depot"])
        for a, b in zip(pts, pts[1:]):
            for nf in self.M["nofly"]:
                if seg_circle(a["x"], a["y"], b["x"], b["y"], nf["x"], nf["y"], nf["r"]):
                    out.append(rej("route", "nofly", "Плечо %s → %s проходит через зону «%s»." % (a["ru"], b["ru"], nf["ru"]), "Leg %s → %s crosses the zone '%s'." % (a["en"], b["en"], nf["en"])))
        u, v = self.wind(30)
        w = math.sqrt(u * u + v * v)
        if w > D["wind_max"]:
            out.append(rej("drone", "wind", "Ветер у склада %.1f м/с, предел дрона 12 м/с." % w, "Wind at the depot %.1f m/s, the drone's limit is 12 m/s." % w))
        p = self.p_hover(D["empty_kg"] + kg, self.M["depot"]["z"]); hr = self.hour()
        if p > hr["pmax"]:
            out.append(rej("route", "heat", "При %.0f °C батарея даёт %.1f кВт, а висение с грузом %.1f кг требует %.1f кВт." % (hr["t"], hr["pmax"] / 1000, kg, p / 1000),
                           "At %.0f °C the battery gives %.1f kW, hovering with %.1f kg needs %.1f kW." % (hr["t"], hr["pmax"] / 1000, kg, p / 1000)))
        return out

    def decide(self, dec):
        r = self.check(dec)
        if r:
            return r
        dr = self.drones[dec["drone"]]
        if dec.get("recall"):
            dr["route"] = dr["route"][:dr["wp"]] + ["depot"]
            if dr["phase"] == "service":
                dr["phase"] = "climb"
            return []
        dr.update(mode="air", route=list(dec["route"]) + ["depot"], wp=0, phase="climb", alt=dec.get("alt", 60), va=SPEEDS[dec.get("speed", "eco")], busy=0.0)
        dr["load"] = [int(t[1:]) for t in dec["route"] if t[0] == "o"]
        for o in dr["load"]:
            self.orders[o].update(status="air", drone=dr["id"])
        self.events.append([self.t, "takeoff", dr["id"]])
        return []

    # ---------- шаг ----------
    def step(self):
        hr = self.hour()
        for dr in self.drones:
            if dr["mode"] == "dock" or dr["mode"] == "pad":
                if dr["busy"] > 0:
                    dr["busy"] -= DT
                    if dr["busy"] <= 0:
                        dr["busy"] = 0.0; dr["soc"] = 1.0
                        if dr["mode"] == "pad":
                            dr["mode"] = "air"; dr["phase"] = "climb"; dr["wp"] += 1
                continue
            if dr["mode"] != "air":
                continue
            m = self.mass(dr); zg = self.ground(dr["x"], dr["y"]); ph = self.p_hover(m, zg + dr["agl"])
            u, v = self.wind(dr["alt"])
            w = math.sqrt(u * u + v * v)
            P = ph
            if dr["phase"] == "climb":
                P = ph * D["climb_k"]; dr["agl"] += D["climb_ms"] * DT
                if dr["agl"] >= dr["alt"]:
                    dr["agl"] = float(dr["alt"]); dr["phase"] = "cruise"
            elif dr["phase"] == "cruise":
                tg = self.target(dr["route"][dr["wp"]]); dx, dy = tg["x"] - dr["x"], tg["y"] - dr["y"]
                dist = math.sqrt(dx * dx + dy * dy)
                ex, ey = (dx / dist, dy / dist) if dist > 0 else (0.0, 0.0)
                wa = u * ex + v * ey; wc = -u * ey + v * ex; va = dr["va"]
                gs = (math.sqrt(va * va - wc * wc) + wa) if wc * wc < va * va else wa
                gs = 0.0 if gs < 0 else gs
                dr["gs"] = gs
                uu = va / 15.0
                P = ph * (1 + CRUISE_A * uu + CRUISE_B * uu * uu)
                step = gs * DT
                if step >= dist:
                    dr["x"], dr["y"] = tg["x"], tg["y"]; dr["phase"] = "descend"
                else:
                    dr["x"] += ex * step; dr["y"] += ey * step
            elif dr["phase"] == "descend":
                P = ph * D["descend_k"]; dr["gs"] = 0.0
                tok = dr["route"][dr["wp"]]; low = 0.0 if tok == "depot" or tok[0] == "p" else 20.0  # заказ опускают тросом с 20 м
                dr["agl"] -= D["climb_ms"] * DT
                if dr["agl"] <= low:
                    dr["agl"] = low
                    if tok == "depot":
                        dr.update(mode="dock", phase="", busy=D["swap_depot_s"], route=[], wp=0)
                        for o in dr["load"]:
                            self.orders[o].update(status="wait", drone=None)  # недоставленное возвращается в очередь
                        dr["load"] = []
                        self.events.append([self.t, "dock", dr["id"]])
                    elif tok[0] == "p":
                        dr.update(mode="pad", busy=D["swap_pad_s"]); self.counts["pads"] += 1; dr["pads"] += 1
                        self.events.append([self.t, "pad", dr["id"], int(tok[1:])])
                    else:
                        dr["phase"] = "service"; dr["busy"] = D["service_s"]
            elif dr["phase"] == "service":
                dr["busy"] -= DT
                if dr["busy"] <= 0:
                    o = int(dr["route"][dr["wp"]][1:]); dr["busy"] = 0.0
                    if o in dr["load"]:
                        dr["load"].remove(o); od = self.orders[o]
                        od.update(status="done", at=self.t + DT)
                        self.counts["delivered"] += 1
                        late = self.t + DT - od["due"]; self.counts["late_s"] += late if late > 0 else 0.0
                        self.events.append([self.t, "deliver", dr["id"], o])
                    dr["wp"] += 1; dr["phase"] = "climb"
            if dr["mode"] != "air":
                continue
            # батарея: ёмкость меньше на морозе, мощность ограничена в жару
            used = P * DT / 3600.0
            dr["wh"] += used; self.counts["wh"] += used
            dr["soc"] -= used / (D["battery_wh"] * hr["cap"])
            if dr["soc"] <= 0:
                self._down(dr, "lost"); continue
            if P > hr["pmax"] or w > D["wind_abort"] or (dr["soc"] < D["reserve"] and dr["phase"] != "descend"):
                self._forced(dr)
        self.t += DT
        if int(self.t) % 10 == 0:
            self._log()

    def _forced(self, dr):
        """Автопилот сажает дрон там, где он есть: у точки, на площадке или на складе это не вынужденная посадка."""
        here = None
        for p in [self.M["depot"]] + self.M["points"]:
            dx, dy = p["x"] - dr["x"], p["y"] - dr["y"]
            if dx * dx + dy * dy < 50 * 50:
                here = p
        if here is self.M["depot"]:
            dr["route"] = dr["route"][:dr["wp"]] + ["depot"]; dr["phase"] = "descend"; return
        if here is not None and here.get("pad"):  # над площадкой: садится на неё и меняет батарею
            if dr["route"][dr["wp"]] != "p%d" % here["id"]:
                dr["route"].insert(dr["wp"], "p%d" % here["id"])
            dr["phase"] = "descend"; return
        self._down(dr, "forced")

    def _down(self, dr, kind):
        dr["mode"] = kind; dr["phase"] = ""; dr["gs"] = 0.0
        self.counts[kind] += 1
        for o in dr["load"]:
            self.orders[o].update(status="lost" if kind == "lost" else "stuck")
        self.events.append([self.t, kind, dr["id"], round(dr["x"]), round(dr["y"])])

    def _log(self):
        self.journal.append({"t": self.t, "d": [[round(d["x"]), round(d["y"]), round(d["agl"]), round(d["soc"] * 1000) / 10, d["mode"], len(d["load"])] for d in self.drones]})

    def done(self):
        if self.t >= END_S:
            return True
        return self.t >= SHIFT_S and all(d["mode"] != "air" and d["mode"] != "pad" for d in self.drones)

    # ---------- что видит игрок ----------
    def observe(self):
        hr = self.hour(); out_d = []
        for d in self.drones:
            u, v = self.wind(d["alt"]) if d["mode"] == "air" else (None, None)
            out_d.append({"id": d["id"], "mode": d["mode"], "phase": d["phase"], "x": d["x"], "y": d["y"], "agl": d["agl"], "soc": d["soc"],
                          "load": list(d["load"]), "load_kg": round(self.mass(d) - D["empty_kg"], 1), "route": d["route"][d["wp"]:], "gs": d["gs"],
                          "busy": d["busy"], "wind_here": None if u is None else [round(u, 2), round(v, 2)]})
        u, v = self.wind(30)
        return {"t": self.t, "clock": clock(self.t), "city": self.city, "drones": out_d,
                "orders": [{"id": o["id"], "point": o["point"], "kg": o["kg"], "due": o["due"], "status": o["status"]} for o in self.orders if o["t"] <= self.t],
                "depot_wind": [round(u, 2), round(v, 2)], "temp_now": hr["t"], "cap_now": hr["cap"], "pmax_now": hr["pmax"],
                "forecast": [{"hour": 12 + k, "t": h["t_fc"], "wind": {a: h["fc"][a] for a in ALTS}} for k, h in enumerate(self.W["hours"])],
                "map": {"depot": self.M["depot"], "points": self.M["points"], "nofly": self.M["nofly"]}}

    # ---------- счёт ----------
    def ref_wh(self, o):
        """Эталон энергии заказа: туда и обратно по прямой в штиль, эконом, 60 м, с грузом туда и пустым обратно."""
        p = self.pts[o["point"]]; d = math.sqrt(p["x"] * p["x"] + p["y"] * p["y"])
        c = 1 + CRUISE_A * 0.8 + CRUISE_B * 0.64
        hl = D["hover_c"] * (D["empty_kg"] + o["kg"]) * math.sqrt(math.sqrt(D["empty_kg"] + o["kg"])); he = D["hover_c"] * D["empty_kg"] * math.sqrt(math.sqrt(D["empty_kg"]))
        return (hl + he) * c * d / 12.0 / 3600.0

    def score(self):
        parts = {}; c = self.counts
        undelivered = sum(1 for o in self.orders if o["status"] != "done")
        ref = sum(self.ref_wh(o) for o in self.orders if o["status"] == "done")
        parts["delivered"] = SC["delivered"] * c["delivered"]
        parts["late"] = -SC["late_per_s"] * c["late_s"]
        parts["undelivered"] = -SC["undelivered"] * undelivered
        parts["forced"] = -SC["forced"] * c["forced"]
        parts["lost"] = -SC["lost"] * c["lost"]
        parts["pads"] = -SC["pad"] * c["pads"]
        e = 0.0
        if ref > 0:
            e = -SC["energy_per_pct"] * (100.0 * c["wh"] / ref - 100.0)
            e = SC["energy_min"] if e < SC["energy_min"] else (SC["energy_max"] if e > SC["energy_max"] else e)
        parts["energy"] = e
        sc = 0.0
        for k in ("delivered", "late", "undelivered", "forced", "lost", "pads", "energy"):
            sc += parts[k]
        sc = SC["base"] + sc
        return {"score": round(sc, 1), "raw": sc, "parts": {k: round(v, 1) for k, v in parts.items()},
                "counts": {"delivered": c["delivered"], "orders": len(self.orders), "late_s": round(c["late_s"]), "forced": c["forced"], "lost": c["lost"],
                           "pads": c["pads"], "kwh": round(c["wh"] / 1000, 2), "ref_kwh": round(ref / 1000, 2)}}


def replay(seed, settings, decisions):
    """Пересчёт смены по журналу решений [[шаг, решение], ...] для таблицы рекордов."""
    city = settings.get("city")
    if city not in CITIES:
        raise ValueError("неизвестный город: %r" % city)
    clean = sorted([(int(s), d) for s, d in decisions], key=lambda x: x[0])
    g = Game(int(seed), city); i = 0; n = 0
    while not g.done():
        while i < len(clean) and clean[i][0] <= n:
            g.decide(clean[i][1]); i += 1
        g.step(); n += 1
    sc = g.score()
    return {"score": sc["score"], "parts": sc["parts"], "counts": sc["counts"], "steps": n}


LANG_VERSION = 2

DEFAULT = {"alt": 60, "speed": "eco", "load_kg": 40.0, "per_flight": 1, "reserve": 15,
           "pad": None, "pad_below": None, "first": "urgent", "max_km": None}

KW = [
    (r"^(высота|altitude) ([0-9]+)$", "alt"),
    (r"^(скорость|speed) (эконом|быстро|eco|fast)$", "speed"),
    (r"^(груз до|load up to) ([0-9]+(?:[.,][0-9]+)?)( кг| kg)?$", "load"),
    (r"^(заказов за рейс|orders per flight) ([0-9]+)$", "per_flight"),
    (r"^(запас|reserve) ([0-9]+)( %|%)?$", "reserve"),
    (r"^(зарядка на площадке|pad) ([0-9]+) (если заряд меньше|if charge below) ([0-9]+)( %|%)?$", "pad"),
    (r"^(сначала|first) (срочные|близкие|тяжёлые|urgent|near|heavy)$", "first"),
    (r"^(не лететь дальше|no farther than) ([0-9]+(?:[.,][0-9]+)?)( км| km)?$", "max_km"),
]
FIRST = {"срочные": "urgent", "urgent": "urgent", "близкие": "near", "near": "near", "тяжёлые": "heavy", "heavy": "heavy"}
SPEED = {"эконом": "eco", "eco": "eco", "быстро": "fast", "fast": "fast"}


def _f(s):
    return float(s.replace(",", "."))


def _n(x):
    return ("%.1f" % x).replace(".", ",")


def _e(i, ru, en):
    return {"line": i, "ru": ("строка %d: " % i if i else "") + ru, "en": ("line %d: " % i if i else "") + en}


def parse(text):
    """-> (план, ошибки). Ошибка: {line, ru, en}."""
    plan = dict(DEFAULT); plan["lines"] = {}
    errs = []
    for i, raw in enumerate(str(text).splitlines(), start=1):
        line = raw.split("#", 1)[0].strip().lower()
        line = " ".join(line.split())
        if not line:
            continue
        for pat, kind in KW:
            m = re.match(pat, line)
            if m:
                break
        else:
            errs.append(_e(i, "«%s» не команда языка полёта." % raw.strip(), "'%s' is not a command of the flight language." % raw.strip()))
            continue
        if kind in plan["lines"]:
            errs.append(_e(i, "такая строка уже есть (строка %d): команда пишется один раз." % plan["lines"][kind],
                           "this command is already on line %d: write it once." % plan["lines"][kind]))
            continue
        plan["lines"][kind] = i
        if kind == "alt":
            plan["alt"] = int(m.group(2))
        elif kind == "speed":
            plan["speed"] = SPEED[m.group(2)]
        elif kind == "load":
            plan["load_kg"] = _f(m.group(2))
        elif kind == "per_flight":
            plan["per_flight"] = int(m.group(2))
        elif kind == "reserve":
            plan["reserve"] = int(m.group(2))
        elif kind == "pad":
            plan["pad"] = int(m.group(2)); plan["pad_below"] = int(m.group(4))
        elif kind == "first":
            plan["first"] = FIRST[m.group(2)]
        elif kind == "max_km":
            plan["max_km"] = _f(m.group(2))
    return plan, errs


def sense(plan, g):
    """Здравый смысл замысла без прогона."""
    errs = []; L = plan["lines"]
    if plan["alt"] not in ALTS:
        errs.append(_e(L.get("alt", 0), "высота %d м: дрон летит на 30, 60, 100 или 120 м." % plan["alt"],
                       "altitude %d m: the drone flies at 30, 60, 100 or 120 m." % plan["alt"]))
    if plan["load_kg"] > D["payload_max"]:
        errs.append(_e(L.get("load", 0), "груз до %s кг: дрон берёт не больше 40 кг." % _n(plan["load_kg"]),
                       "load up to %s kg: the drone takes at most 40 kg." % _n(plan["load_kg"])))
    if plan["load_kg"] < 2:
        errs.append(_e(L.get("load", 0), "груз до %s кг: самый легкий заказ 2 кг, с таким пределом не полетит ни один." % _n(plan["load_kg"]),
                       "load up to %s kg: the lightest order is 2 kg, nothing would fly." % _n(plan["load_kg"])))
    if plan["per_flight"] < 1 or plan["per_flight"] > 3:
        errs.append(_e(L.get("per_flight", 0), "заказов за рейс %d: за рейс берут от 1 до 3 заказов." % plan["per_flight"],
                       "orders per flight %d: a flight takes 1 to 3 orders." % plan["per_flight"]))
    if plan["reserve"] < 5 or plan["reserve"] > 60:
        errs.append(_e(L.get("reserve", 0), "запас %d %%: запас на складе от 5 до 60 процентов (ниже 8 %% дрон садится сам)." % plan["reserve"],
                       "reserve %d%%: keep 5 to 60 percent (below 8%% the autopilot lands)." % plan["reserve"]))
    if plan["pad"] is not None:
        p = g.pts.get(plan["pad"])
        if p is None or not p["pad"]:
            pads = ", ".join(str(q["id"]) for q in g.M["points"] if q["pad"])
            errs.append(_e(L.get("pad", 0), "точка %d не площадка зарядки; площадки: %s." % (plan["pad"], pads),
                           "point %d is not a charging pad; pads: %s." % (plan["pad"], pads)))
    if plan["max_km"] is not None:
        near = min(math.sqrt(p["x"] * p["x"] + p["y"] * p["y"]) for p in g.M["points"]) / 1000.0
        if plan["max_km"] < near:
            errs.append(_e(L.get("max_km", 0), "не лететь дальше %s км: ближняя точка города в %s км от склада, летать будет некуда." % (_n(plan["max_km"]), _n(near)),
                           "no farther than %s km: the nearest point is %s km from the depot, nothing would fly." % (_n(plan["max_km"]), _n(near))))
    return errs


# ---------- расчёт круга по прогнозу ----------
def fc_wind(g, t, alt):
    """Прогноз ветра на высоте alt в момент t: вектор «куда», м/с."""
    hs = g.W["hours"]; f = t / 3600.0 + 1.0
    i = int(f)
    i = 0 if i < 0 else (len(hs) - 2 if i > len(hs) - 2 else i)
    a = f - i
    a = 0.0 if a < 0 else (1.0 if a > 1 else a)
    u = hs[i]["fc"][alt][0] * (1 - a) + hs[i + 1]["fc"][alt][0] * a
    v = hs[i]["fc"][alt][1] * (1 - a) + hs[i + 1]["fc"][alt][1] * a
    return u, v


WIND_K = 1.18   # объявленная в правилах ошибка прогноза по силе ветра: обработчик считает круг по худшему краю


def ground_speed(va, u, v, ex, ey, k=1.0):
    """Путевая скорость и встречная составляющая ветра на курсе.

    k > 1: считать по худшему краю прогноза. Попутный ветер берётся слабее, встречный и боковой сильнее:
    ошибка прогноза объявлена в правилах (±18 % по силе), и дрон не должен зависеть от того, в какую сторону она легла.
    """
    wa = u * ex + v * ey; wc = -u * ey + v * ex
    wa = wa / k if wa > 0 else wa * k
    wc = wc * k
    gs = (math.sqrt(va * va - wc * wc) + wa) if wc * wc < va * va else wa
    return (0.0 if gs < 0 else gs), -wa


def flight(g, stops, kgs, alt, va, t0, soc0, cap):
    """Круг по прогнозу: склад -> stops -> склад. Фазы как в симуляторе (подъём, полёт, спуск, выгрузка).

    stops: [(точка карты, вид)], вид «order» (груз опускают тросом с 20 м) или «pad» (садится и меняет батарею);
    kgs: груз на борту на каждом плече (кг).
    -> {ok, soc, t, legs}: legs = [{from, to, dist, gs, head, wh, soc, km_left}]
    """
    pts = [(g.M["depot"], "depot")] + list(stops) + [(g.M["depot"], "depot")]
    e = D["battery_wh"] * cap
    t = t0; soc = soc0; legs = []; pneed = 0.0
    for k in range(len(pts) - 1):
        (a, _), (b, kind) = pts[k], pts[k + 1]
        kg = kgs[k] if k < len(kgs) else 0.0
        m = D["empty_kg"] + kg
        ph_mid = D["hover_c"] * m * math.sqrt(math.sqrt(m)) * g.dens((a["z"] + b["z"]) / 2.0 + alt)
        ph_a = D["hover_c"] * m * math.sqrt(math.sqrt(m)) * g.dens(a["z"] + alt / 2.0)
        low = 20.0 if kind == "order" else 0.0
        pneed = max(pneed, ph_a * D["climb_k"])   # подъём стоит на 15 % больше висения: в жару упирается в батарею
        wh = ph_a * D["climb_k"] * (alt / D["climb_ms"]) / 3600.0          # подъём
        wh += ph_a * D["descend_k"] * ((alt - low) / D["climb_ms"]) / 3600.0  # спуск
        dx, dy = b["x"] - a["x"], b["y"] - a["y"]
        dist = math.sqrt(dx * dx + dy * dy)
        ex, ey = (dx / dist, dy / dist) if dist > 0 else (0.0, 0.0)
        u, v = fc_wind(g, t + alt / D["climb_ms"], alt)
        gs, head = ground_speed(va, u, v, ex, ey, WIND_K)
        uu = va / 15.0
        p_cr = ph_mid * (1 + CRUISE_A * uu + CRUISE_B * uu * uu)
        if gs < 0.5:
            cr_s = 1e9; wh += 1e9
        else:
            cr_s = dist / gs; wh += p_cr * cr_s / 3600.0
        if low > 0:
            wh += ph_a * D["service_s"] / 3600.0                                # выгрузка с висения
        soc_a = soc; soc = soc - wh / e
        km_left = 0.0
        if soc_a > 0 and wh > 0 and dist > 0 and gs >= 0.5:
            share = (soc_a - D["reserve"]) * e / wh
            share = 0.0 if share < 0 else (1.0 if share > 1 else share)
            km_left = dist * share / 1000.0
        legs.append({"from": a, "to": b, "dist": dist, "gs": gs, "head": head, "wh": wh, "soc": soc, "km_left": km_left})
        t += alt / D["climb_ms"] + (alt - low) / D["climb_ms"] + (cr_s if cr_s < 1e8 else 0.0) + (D["service_s"] if low > 0 else 0.0)
        if kind == "pad":
            soc = 1.0; t += D["swap_pad_s"]
    return {"ok": soc > 0, "soc": soc, "t": t, "legs": legs, "pneed": pneed}


def fc_pmax(g, t0, t1):
    """Наименьшая мощность батареи по прогнозу на часы рейса."""
    hs = g.W["hours"]; out = None
    for k, h in enumerate(hs):
        a0 = (k - 1) * 3600.0; a1 = a0 + 3600.0
        if a1 > t0 and a0 < t1 + 1:
            out = h["pmax"] if out is None else min(out, h["pmax"])
    return out if out is not None else hs[min(len(hs) - 1, 1)]["pmax"]


class Dispatcher:
    """Обработчик: ведёт смену по замыслу. Каждые 5 с смотрит свободные дроны и считает круг по прогнозу."""

    def __init__(self, plan):
        self.p = plan; self.refused = {}; self.launched = 0

    @property
    def refusals(self):
        return list(self.refused.values())

    def _cands(self, g):
        out = []
        for o in g.orders:
            if o["status"] != "wait" or o["t"] > g.t:
                continue
            p = g.pts[o["point"]]
            d = math.sqrt(p["x"] * p["x"] + p["y"] * p["y"])
            if self.p["max_km"] is not None and d > 1000.0 * self.p["max_km"]:
                continue
            if o["kg"] > self.p["load_kg"]:
                continue
            out.append((o, p, d))
        if self.p["first"] == "near":
            out.sort(key=lambda r: (r[2], r[0]["id"]))
        elif self.p["first"] == "heavy":
            out.sort(key=lambda r: (-r[0]["kg"], r[0]["id"]))
        else:
            out.sort(key=lambda r: (r[0]["due"], r[0]["id"]))
        return out

    def _try(self, g, dr, picked, cap):
        """Собрать рейс из выбранных заказов: с площадкой, если так сказано, и без неё. -> (decision, расчёт) или (None, расчёт)."""
        alt = self.p["alt"]; va = SPEEDS[self.p["speed"]]
        stops = [(p, "order") for _, p, _ in picked]
        kgs = []
        total = sum(o["kg"] for o, _, _ in picked)
        left = total
        kgs.append(left)
        for o, _, _ in picked:
            left -= o["kg"]; kgs.append(left)
        f = flight(g, stops, kgs, alt, va, g.t, dr["soc"], g.hour()["cap"])
        need = self.p["reserve"] / 100.0
        route = ["o%d" % o["id"] for o, _, _ in picked]
        f["pmax"] = fc_pmax(g, g.t, f["t"])
        if f["pneed"] > f["pmax"]:        # подъём с таким грузом в такую жару батарея не даёт
            return None, f
        if f["soc"] >= need:
            return {"drone": dr["id"], "route": route, "alt": alt, "speed": self.p["speed"]}, f
        pad = g.pts.get(self.p["pad"]) if self.p["pad"] is not None else None
        if pad is not None and pad["pad"] and f["soc"] < self.p["pad_below"] / 100.0:
            f2 = flight(g, stops + [(pad, "pad")], kgs + [0.0], alt, va, g.t, dr["soc"], g.hour()["cap"])
            if f2["soc"] >= need and all(l["soc"] > D["reserve"] for l in f2["legs"]):
                return {"drone": dr["id"], "route": route + ["p%d" % pad["id"]], "alt": alt, "speed": self.p["speed"]}, f2
            f = f2 if f2["soc"] > f["soc"] else f
        return None, f

    def tick(self, g):
        """-> список решений на этот шаг."""
        if int(g.t) % 5:
            return []
        out = []
        for dr in g.drones:
            if dr["mode"] != "dock" or dr["busy"] > 0 or dr["route"]:
                continue
            cands = self._cands(g)
            if not cands:
                continue
            taken = set()
            for d in out:
                for tok in d["route"]:
                    if tok[0] == "o":
                        taken.add(int(tok[1:]))
            cands = [c for c in cands if c[0]["id"] not in taken]
            if not cands:
                continue
            flew = False
            for head in cands:          # заказ, который не закрывается по прогнозу, не держит остальную ленту
                group = [head]
                for _ in range(self.p["per_flight"] - 1):
                    rest = [c for c in cands if c not in group and sum(o["kg"] for o, _, _ in group) + c[0]["kg"] <= self.p["load_kg"]]
                    if not rest:
                        break
                    lp = group[-1][1]
                    rest.sort(key=lambda c: ((c[1]["x"] - lp["x"]) ** 2 + (c[1]["y"] - lp["y"]) ** 2, c[0]["id"]))
                    group.append(rest[0])
                while group:
                    dec, f = self._try(g, dr, group, g.hour()["cap"])
                    if dec is not None and not g.check(dec):
                        out.append(dec); self.launched += 1; flew = True
                        break
                    if len(group) == 1:
                        self._refuse(g, dr, group, f, dec)
                        break
                    group = group[:-1]
                if flew:
                    break
        return out

    def _refuse(self, g, dr, group, f, dec):
        """Записать, почему один заказ не взлетел: встречный ветер обратного плеча и где кончится заряд."""
        o, p, d = group[0]
        why = "heat" if f.get("pneed", 0.0) > f.get("pmax", 1e9) else "charge"
        if dec is not None:
            r = g.check(dec)
            why = r[0]["code"] if r else "charge"
        back = f["legs"][-1] if f["legs"] else None
        self.refused[o["id"]] = ({"t": g.t, "order": o["id"], "point": p["id"], "point_ru": p["ru"], "point_en": p["en"],
                              "kg": o["kg"], "km": d / 1000.0, "why": why, "soc": f["soc"],
                              "head": (back["head"] if back else 0.0), "km_left": (back["km_left"] if back else 0.0),
                              "dist_back": (back["dist"] / 1000.0 if back else 0.0)})


# ---------- мир по прогнозу ----------
def typical_orders(city, points):
    """Типовая лента заказов города: та же рука, что в мире, но не те заказы, что придут (их до смены никто не знает)."""
    ro = Rng(fnv("typical:" + city)); orders = []
    n = 12 + int(ro.u() * 5)
    for i in range(n):
        t = int(ro.u() * 5400)
        p = points[int(ro.u() * len(points))]
        kg = round(2 + 28 * ro.u() * ro.u(), 1)
        orders.append({"t": t, "point": p["id"], "kg": kg, "due": t + 1500 + int(ro.u() * 1500)})
    orders.sort(key=lambda o: (o["t"], o["point"]))
    for i, o in enumerate(orders):
        o["id"] = i
    return orders


def expected_world(g, k=1.0):
    """То, что известно до смены: прогноз ветра и температуры этого дня, без порывов, типовая лента заказов.

    k > 1: худший край прогноза, ветер сильнее на объявленную ошибку. Прогноз в этом мире остаётся прежним:
    обработчик видит то же, что видел бы в смену, а мир идёт по худшему краю.
    """
    W = g.W; zc = W["map"]["depot"]["z"]; hours = []
    for h in W["hours"]:
        t2 = h["t_fc"]; dens = []
        for z in range(0, 3100, 100):
            T = t2 + 273.15 - 0.0065 * (z - zc)
            pr = 101325.0 * (1 - 2.25577e-5 * z) ** 5.25588
            dens.append(math.sqrt(1.225 / (pr / (287.05 * T))))
        cap = 1.0 if t2 >= 15 else (0.85 + 0.15 * t2 / 15.0 if t2 >= 0 else (0.85 + 0.015 * t2 if t2 >= -20 else 0.55))
        pmax = D["pmax_w"] if t2 <= D["pmax_hot_c"] else max(
            D["pmax_46_w"], D["pmax_w"] - (t2 - D["pmax_hot_c"]) * (D["pmax_w"] - D["pmax_46_w"]) / 6.0)
        truth = h["fc"] if k == 1.0 else {a: [k * h["fc"][a][0], k * h["fc"][a][1]] for a in h["fc"]}
        hours.append({"truth": truth, "fc": h["fc"], "t": t2, "t_fc": t2, "dens": dens, "cap": cap, "pmax": pmax, "gust_k": 0.0})
    return {"seed": W["seed"], "city": W["city"], "day": W["day"], "hours": hours,
            "gust": [1.0] * len(W["gust"]), "orders": typical_orders(W["city"], W["map"]["points"]), "map": W["map"]}


def simulate(plan, g0, world=None):
    """Прогон смены по замыслу. -> (игра, обработчик)."""
    g = Game(g0.W["seed"], g0.city, world=world if world is not None else expected_world(g0))
    disp = Dispatcher(plan)
    while not g.done():
        for dec in disp.tick(g):
            g.decide(dec)
        g.step()
    return g, disp


def _fc(g, disp):
    sc = g.score(); c = sc["counts"]
    return {"score": sc["score"], "delivered": c["delivered"], "orders": c["orders"], "forced": c["forced"], "lost": c["lost"],
            "pads": c["pads"], "kwh": c["kwh"], "ref_kwh": c["ref_kwh"], "flights": disp.launched, "refused": len(disp.refusals)}


LINE_RU = {"alt": "высота", "speed": "скорость", "load": "груз до", "per_flight": "заказов за рейс", "reserve": "запас",
           "pad": "зарядка на площадке", "first": "сначала", "max_km": "не лететь дальше"}
LINE_EN = {"alt": "altitude", "speed": "speed", "load": "load up to", "per_flight": "orders per flight", "reserve": "reserve",
           "pad": "pad", "first": "first", "max_km": "no farther than"}
MARGIN = 30.0
GAIN = 60.0     # совет по строке показывается, когда одна строка даёт столько очков по прогнозу


def variants(plan, g):
    """Что стоит попробовать: замена или добавление одной строки. -> [(строка ru, строка en, план, (поле, значение))].

    Ступень 2 языка (13.11, по ошибкам прогона ступени 1): модель написала один и тот же осторожный замысел
    во все 30 смен, и Проверка молчала, потому что отказывает только на замысле, который хуже. Теперь Проверка
    вместе с прогнозом отдаёт разницу в счёте от одной строки, и модель получает её до смены.
    """
    out = []
    pads = [q["id"] for q in g.M["points"] if q["pad"]]

    def mk(**kw):
        p = dict(plan); p["lines"] = dict(plan["lines"]); p.update(kw); return p

    out.append(("со строкой «скорость быстро»", "with the line 'speed fast'", mk(speed="fast"), ("speed", "fast")) if plan["speed"] != "fast"
               else ("со строкой «скорость эконом»", "with the line 'speed eco'", mk(speed="eco"), ("speed", "eco")))
    out.append(("со строкой «заказов за рейс 2»", "with the line 'orders per flight 2'", mk(per_flight=2), ("per_flight", 2)) if plan["per_flight"] != 2
               else ("со строкой «заказов за рейс 3»", "with the line 'orders per flight 3'", mk(per_flight=3), ("per_flight", 3)))
    for a in (30, 60):
        if plan["alt"] != a:
            out.append(("со строкой «высота %d»" % a, "with the line 'altitude %d'" % a, mk(alt=a), ("alt", a)))
    if plan["reserve"] > 10:
        out.append(("со строкой «запас 10»", "with the line 'reserve 10'", mk(reserve=10), ("reserve", 10)))
    if plan["max_km"] is not None:
        out.append(("без строки «не лететь дальше %s км»" % _n(plan["max_km"]),
                    "without the line 'no farther than %s km'" % _n(plan["max_km"]), mk(max_km=None), ("max_km", None)))
    if plan["load_kg"] < D["payload_max"]:
        out.append(("со строкой «груз до 40 кг»", "with the line 'load up to 40 kg'", mk(load_kg=D["payload_max"]), ("load_kg", D["payload_max"])))
    if plan["pad"] is None and pads:
        out.append(("со строкой «зарядка на площадке %d если заряд меньше 45»" % pads[0],
                    "with the line 'pad %d if charge below 45'" % pads[0], mk(pad=pads[0], pad_below=45), ("pad", pads[0])))
    elif plan["pad"] is not None:
        out.append(("без строки «зарядка на площадке %d»" % plan["pad"],
                    "without the line 'pad %d'" % plan["pad"], mk(pad=None, pad_below=None), ("pad", None)))
    return out


def advice(plan, g0, worlds, mine, mine18):
    """Строка, которая по прогнозу даёт больше всех очков (и на прогнозе, и на худшем крае). -> dict или None."""
    best = None
    for ru, en, p, key in variants(plan, g0):
        got = _fc(*simulate(p, g0, worlds[0]))
        if got["score"] <= mine["score"] + GAIN:
            continue
        got18 = _fc(*simulate(p, g0, worlds[1]))
        if got18["score"] <= mine18["score"] + GAIN:
            continue
        if best is None or got["score"] > best["score"]:
            best = {"line_ru": ru, "line_en": en, "field": key[0], "value": key[1], "score": got["score"], "delivered": got["delivered"],
                    "forced": got["forced"], "base_score": mine["score"], "base_delivered": mine["delivered"],
                    "orders": mine["orders"]}
    if best is None:
        return None
    best["ru"] = ("по прогнозу этот замысел даёт %s очков (доставлено %d из %d); %s вышло бы %s (доставлено %d)."
                  % (_n(best["base_score"]), best["base_delivered"], best["orders"], best["line_ru"], _n(best["score"]), best["delivered"]))
    best["en"] = ("by the forecast this plan scores %s (%d of %d delivered); %s it would score %s (%d delivered)."
                  % (_n(best["base_score"]), best["base_delivered"], best["orders"], best["line_en"], _n(best["score"]), best["delivered"]))
    return best


def _wind_shift(g, alt):
    """Наибольшая сила ветра по прогнозу на этой высоте за часы смены."""
    out = 0.0
    for t in range(0, SHIFT_S + 1, 600):
        u, v = fc_wind(g, t, alt)
        s = math.sqrt(u * u + v * v)
        out = s if s > out else out
    return out


def _reason(kind, plan, g, disp, mine, base, hint):
    """Отказ по строке: причина с цифрами. hint = худший отказ взлёта на прогоне плана."""
    i = plan["lines"][kind]; d = mine["delivered"]; db = base["delivered"]
    tail_ru = "по прогнозу доставлено %d из %d против %d без этой строки, счёт %s против %s" % (d, mine["orders"], db, _n(mine["score"]), _n(base["score"]))
    tail_en = "by the forecast %d of %d delivered against %d without this line, score %s against %s" % (d, mine["orders"], db, _n(mine["score"]), _n(base["score"]))
    if kind == "reserve":
        return _e(i, "запас %d %% не даёт взлететь: по прогнозу %d заказов из %d остаются на складе, %s." % (plan["reserve"], mine["orders"] - mine["delivered"], mine["orders"], tail_ru),
                  "the %d%% reserve blocks take-offs: by the forecast %d orders of %d stay at the depot, %s." % (plan["reserve"], mine["orders"] - mine["delivered"], mine["orders"], tail_en))
    if kind == "alt":
        w_plan = _wind_shift(g, plan["alt"]); w_def = _wind_shift(g, DEFAULT["alt"])
        zc = g.M["depot"]["z"]
        ph = D["hover_c"] * D["empty_kg"] * math.sqrt(math.sqrt(D["empty_kg"])) * g.dens(zc + plan["alt"] / 2.0)
        dz = (plan["alt"] - DEFAULT["alt"]) / D["climb_ms"]
        dwh = ph * (D["climb_k"] + D["descend_k"]) * dz / 3600.0
        return _e(i, "на %d м ветер по прогнозу %s м/с (на %d м %s м/с), а подъём и спуск стоят на %s Вт·ч за остановку больше: %s." % (
            plan["alt"], _n(w_plan), DEFAULT["alt"], _n(w_def), _n(dwh), tail_ru),
            "at %d m the forecast wind is %s m/s (at %d m it is %s m/s) and climb plus descent cost %s Wh more per stop: %s." % (
                plan["alt"], _n(w_plan), DEFAULT["alt"], _n(w_def), _n(dwh), tail_en))
    if hint is not None and hint["head"] > 3.0 and kind in ("load", "per_flight", "speed"):
        pads = [q for q in g.M["points"] if q["pad"]]
        low_ru = "лети ниже" if plan["alt"] > 30 else "лети быстро"
        low_en = "fly lower" if plan["alt"] > 30 else "fly fast"
        pad_ru = (" или садись на зарядку на площадке %d" % pads[0]["id"]) if (plan["pad"] is None and pads) else ""
        pad_en = (" or recharge on pad %d" % pads[0]["id"]) if (plan["pad"] is None and pads) else ""
        if kind == "load":
            add_ru = "подними предел груза, " + low_ru + pad_ru; add_en = "raise the load limit, " + low_en + pad_en
        elif kind == "per_flight":
            add_ru = "бери по одному заказу, " + low_ru + pad_ru; add_en = "take one order per flight, " + low_en + pad_en
        else:
            add_ru = "лети быстро: времени в воздухе меньше" + pad_ru; add_en = "fly fast: less time in the air" + pad_en
        return _e(i, "на обратном плече встречный ветер %s м/с, заряда хватит до %s км от склада (%s в %s км, груз %s кг): %s. Иначе %s." % (
            _n(hint["head"]), _n(hint["km_left"]), hint["point_ru"], _n(hint["km"]), _n(hint["kg"]), add_ru, tail_ru),
            "headwind %s m/s on the leg home, the charge lasts %s km from the depot (%s at %s km, load %s kg): %s. Otherwise %s." % (
                _n(hint["head"]), _n(hint["km_left"]), hint["point_en"], _n(hint["km"]), _n(hint["kg"]), add_en, tail_en))
    if kind == "max_km":
        return _e(i, "предел %s км оставляет без доставки дальние точки: %s." % (_n(plan["max_km"]), tail_ru),
                  "the %s km limit leaves the far points undelivered: %s." % (_n(plan["max_km"]), tail_en))
    if kind == "speed" and plan["speed"] == "fast":
        return _e(i, "быстро стоит энергии: %s кВт·ч против %s кВт·ч без этой строки, %s." % (_n(mine["kwh"]), _n(base["kwh"]), tail_ru),
                  "fast costs energy: %s kWh against %s kWh without this line, %s." % (_n(mine["kwh"]), _n(base["kwh"]), tail_en))
    if kind == "pad":
        return _e(i, "зарядка на площадке %d не нужна по этому прогнозу: %s." % (plan["pad"], tail_ru),
                  "recharging on pad %d is not needed by this forecast: %s." % (plan["pad"], tail_en))
    if mine["forced"] > base["forced"] or mine["lost"] > base["lost"]:
        return _e(i, "вынужденных посадок %d и потерь %d против %d и %d без этой строки: %s." % (
            mine["forced"], mine["lost"], base["forced"], base["lost"], tail_ru),
            "%d forced landings and %d losses against %d and %d without this line: %s." % (
                mine["forced"], mine["lost"], base["forced"], base["lost"], tail_en))
    return _e(i, "строка «%s» по прогнозу хуже: %s." % (LINE_RU[kind], tail_ru), "the line '%s' is worse by the forecast: %s." % (LINE_EN[kind], tail_en))


def check(text, g0):
    """Полная Проверка замысла до взлёта: -> (ok, отказы, прогноз, план)."""
    plan, errs = parse(text)
    if errs:
        return False, errs, None, plan
    errs = sense(plan, g0)
    if errs:
        return False, errs, None, plan
    worlds = [expected_world(g0), expected_world(g0, WIND_K)]
    g, disp = simulate(plan, g0, worlds[0])
    mine = _fc(g, disp)
    mine18 = _fc(*simulate(plan, g0, worlds[1]))
    base = _fc(*simulate(dict(DEFAULT, lines={}), g0, worlds[0]))
    base18 = _fc(*simulate(dict(DEFAULT, lines={}), g0, worlds[1]))
    if not plan["lines"] or mine["score"] >= base["score"] - MARGIN or mine18["score"] >= base18["score"] - MARGIN:
        mine["advice"] = advice(plan, g0, worlds, mine, mine18)   # замысел принят, но Проверка говорит, что даёт одна строка
        return True, [], mine, plan        # хуже только на одном краю прогноза: это выбор замысла, а не ошибка
    hint = None
    if disp.refusals:
        hint = max(disp.refusals, key=lambda r: r["head"])
    worst = None
    for kind in plan["lines"]:
        cut = dict(plan); cut["lines"] = {k: v for k, v in plan["lines"].items() if k != kind}
        for key, val in (("alt", "alt"), ("speed", "speed"), ("load", "load_kg"), ("per_flight", "per_flight"),
                         ("reserve", "reserve"), ("first", "first"), ("max_km", "max_km")):
            if kind == key:
                cut[val] = DEFAULT[val]
        if kind == "pad":
            cut["pad"] = None; cut["pad_below"] = None
        got = _fc(*simulate(cut, g0, worlds[0]))
        got18 = _fc(*simulate(cut, g0, worlds[1]))
        if got["score"] > mine["score"] + MARGIN and got18["score"] > mine18["score"] + MARGIN and (worst is None or got["score"] > worst[1]["score"]):
            worst = (kind, got)
    if worst is None:
        mine["advice"] = advice(plan, g0, worlds, mine, mine18)
        return True, [], mine, plan
    errs.append(_reason(worst[0], plan, g0, disp, mine, worst[1], hint))
    return False, errs, mine, plan


def run(text, seed, city):
    """Смена по принятому замыслу в настоящем мире (со скрытым ветром и порывами)."""
    g = Game(seed, city)
    plan, _ = parse(text)
    disp = Dispatcher(plan)
    decisions = []; n = 0
    while not g.done():
        for dec in disp.tick(g):
            if not g.decide(dec):
                decisions.append([n, dec])
        g.step(); n += 1
    return g, disp, decisions
